from __future__ import annotations

import atexit
import os
import socket
import subprocess
import tempfile
import time
import uuid
from importlib.resources import files
from pathlib import Path
from typing import Any

_DAEMON_PROCESS: subprocess.Popen[bytes] | None = None
_DAEMON_SOCKET: str | None = None


def _get_daemon_startup_timeout_s() -> float:
    raw_timeout = os.environ.get("ARTIFACT_TOOL_RPC_DAEMON_STARTUP_TIMEOUT_S")
    if raw_timeout is None or raw_timeout == "":
        return 5.0
    return float(raw_timeout)


def _make_socket_address() -> str:
    if os.name != "nt":
        return f"/tmp/artifact_tool_rpc_{os.getpid()}_{uuid.uuid4().hex}.sock"

    return "tcp://127.0.0.1:0"


def _make_ready_file_path(socket_path: str) -> str | None:
    if not socket_path.startswith("tcp://"):
        return None
    return os.path.join(
        tempfile.gettempdir(),
        f"artifact_tool_rpc_{os.getpid()}_{uuid.uuid4().hex}.ready",
    )


def _is_tcp_socket_ready(socket_path: str) -> bool:
    _, _, address = socket_path.partition("tcp://")
    host, _, port = address.partition(":")
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.1)
        return sock.connect_ex((host, int(port))) == 0


def _get_daemon_command() -> list[str] | None:
    try:
        bin_dir = files("artifact_tool_v2") / "bin"
        if os.name == "nt":
            daemon_binary = bin_dir / "artifact_tool_rpc_daemon.exe"
            daemon_script = bin_dir / "artifact_tool_rpc_daemon.js"
            if daemon_binary.is_file() and daemon_script.is_file():
                return [str(daemon_binary), str(daemon_script)]
            return None

        binary = bin_dir / "artifact_tool_rpc_daemon"
        if not binary.is_file():
            return None

        binary_path = Path(str(binary))
        if not os.access(binary_path, os.X_OK):
            os.chmod(binary_path, 0o755)
        return [str(binary_path)]
    except Exception:
        return None


def _get_daemon_popen_kwargs(command: list[str], env: dict[str, str]) -> dict[str, Any]:
    kwargs: dict[str, Any] = {
        "env": env,
        "stdout": None,  # inherit caller stdout
        "stderr": None,  # inherit caller stderr
        "cwd": str(Path(command[0]).parent),
    }
    if os.name != "nt":
        kwargs["start_new_session"] = True
    return kwargs


def start_daemon() -> str:
    """
    Launch the bundled daemon and return its socket path.
    """
    global _DAEMON_PROCESS, _DAEMON_SOCKET

    command = _get_daemon_command()

    if command is None:
        raise ValueError(
            "Bundled daemon binary was not found. Please set ARTIFACT_TOOL_RPC_SOCKET to an existing daemon."
        )

    socket_path = _make_socket_address()
    ready_file_path = _make_ready_file_path(socket_path)

    env = os.environ.copy()
    env["ARTIFACT_TOOL_RPC_SOCKET"] = socket_path
    if ready_file_path is not None:
        env["ARTIFACT_TOOL_RPC_READY_FILE"] = ready_file_path
    proc = subprocess.Popen(
        command,
        **_get_daemon_popen_kwargs(command, env),
    )
    _DAEMON_PROCESS = proc
    try:
        deadline = time.time() + _get_daemon_startup_timeout_s()
        while time.time() < deadline:
            if proc.poll() is not None:
                raise RuntimeError("Failed to start artifact tool daemon (exited early)")
            if ready_file_path is not None and os.path.exists(ready_file_path):
                resolved_socket_path = Path(ready_file_path).read_text().strip()
                if resolved_socket_path.startswith("tcp://") and _is_tcp_socket_ready(
                    resolved_socket_path
                ):
                    socket_path = resolved_socket_path
                    break
            elif os.path.exists(socket_path):
                break
            time.sleep(0.05)
        else:
            raise TimeoutError(
                "Timed out waiting for artifact tool daemon socket. "
                "Set ARTIFACT_TOOL_RPC_DAEMON_STARTUP_TIMEOUT_S=<seconds> to increase the limit."
            )
    except Exception:
        _cleanup_daemon(proc, socket_path, ready_file_path)
        raise

    _DAEMON_SOCKET = socket_path
    if ready_file_path is not None and os.path.exists(ready_file_path):
        os.unlink(ready_file_path)
    return socket_path


def _cleanup_daemon(
    proc: subprocess.Popen[bytes] | None,
    socket_path: str | None,
    ready_file_path: str | None = None,
) -> None:
    global _DAEMON_PROCESS, _DAEMON_SOCKET
    try:
        if proc and proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except Exception:
                pass
        if proc and proc.poll() is None:
            try:
                proc.kill()
            except Exception:
                pass
        if socket_path and not socket_path.startswith("tcp://") and os.path.exists(socket_path):
            try:
                os.unlink(socket_path)
            except Exception:
                pass
        if ready_file_path and os.path.exists(ready_file_path):
            try:
                os.unlink(ready_file_path)
            except Exception:
                pass
    finally:
        _DAEMON_PROCESS = None
        _DAEMON_SOCKET = None


def _stop_daemon_if_started() -> None:
    global _DAEMON_PROCESS, _DAEMON_SOCKET
    _cleanup_daemon(_DAEMON_PROCESS, _DAEMON_SOCKET)


atexit.register(_stop_daemon_if_started)
